          ctx.fillRect(c.x + 6, c.y - 44, 10, 12); ctx.fillRect(c.x + 24, c.y - 38, 10, 12);
          ctx.strokeStyle = PAL.burgundy; ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(c.x - 31, c.y - 40); ctx.lineTo(c.x - 11, c.y - 36);
